  p_type text,
  p_payload jsonb,
  p_idempotency_key text,
  p_heavy boolean default false,
  p_status public.job_status default 'queued',
  p_run_after timestamptz default now(),
  p_event_id uuid default null,
  p_recipe_id uuid default null,
